# Calculate the sum of all integers from 1 to 576 inclusive that are divisible by 7 or by 8

def sum_divisible_by(n, limit):
    """Sum of multiples of n up to limit"""
    k = limit // n
    return n * k * (k + 1) // 2

def sum_divisible_by_7_or_8(limit):
    # Inclusion-exclusion: sum(div by 7) + sum(div by 8) - sum(div by lcm(7,8)=56)
    return sum_divisible_by(7, limit) + sum_divisible_by(8, limit) - sum_divisible_by(56, limit)

ans = sum_divisible_by_7_or_8(576)
print(ans)

